// SYNTHETIC replay fixture: OpenMP form of a made-up sum program.
#include <cstdio>

int main(int argc, char **argv) {
    const int count = 8;
    int total = 0;
    #pragma omp target teams distribute parallel for map(tofrom: total) reduction(+: total)
    for (int k = 0; k < count; k++) {
        total += k;
    }
    printf("replay total %d\n", total);
    printf("PASS\n");
    return 0;
}

