// SYNTHETIC replay fixture: CUDA form of a made-up sum program.
#include <cstdio>

__global__ void replay_sum(int *replay_total, int count) {
    int k = blockIdx.x * blockDim.x + threadIdx.x;
    if (k < count) atomicAdd(replay_total, k);
}

int main(int argc, char **argv) {
    const int count = 8;
    int total = 0;
    int *replay_total;
    cudaMalloc(&replay_total, sizeof(int));
    cudaMemcpy(replay_total, &total, sizeof(int), cudaMemcpyHostToDevice);
    replay_sum<<<1, count>>>(replay_total, count);
    cudaMemcpy(&total, replay_total, sizeof(int), cudaMemcpyDeviceToHost);
    cudaFree(replay_total);
    printf("replay total %d\n", total);
    printf("PASS\n");
    return 0;
}

